from typing import List
from collections import Counter

def numoffbt(arr: List[int], n: int) -> int:
    MOD = 1000000007
    arr = list(set(arr))  # Remove duplicates
    arr.sort()
    count = Counter(arr)
    dp = {x: count[x] for x in arr}

    for x in arr:
        for y in arr:
            if x * y > 100000:
                break
            if x * y in dp:
                dp[x * y] = (dp.get(x * y, 0) + dp[x] * dp[y] % MOD) % MOD
                if x != y:
                    dp[x * y] = (dp[x * y] + dp[x] * dp[y] % MOD) % MOD

    total = sum(dp.values()) % MOD
    return total
